import{_ as n,a0 as r,w as p,s as l,ao as u,I as a,x as o,a1 as e,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu","title":"如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版","tag":"201703","desc":""},"relativePath":"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu.md","filePath":"[post].md"}'),c={name:"201703/20170220 How to create your own Linux Distribution with Yocto on Ubuntu.md"};function d(g,t,h,w,b,m){const i=r("Link");return p(),l("div",null,[t[13]||(t[13]=u('<h1 id="如何在-ubuntu-上用-yocto-创建你自己的-linux-发行版" tabindex="-1">如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版 <a class="header-anchor" href="#如何在-ubuntu-上用-yocto-创建你自己的-linux-发行版" aria-label="Permalink to “如何在 Ubuntu 上用 Yocto 创建你自己的 Linux 发行版”">​</a></h1><h3 id="本文内容" tabindex="-1">本文内容 <a class="header-anchor" href="#本文内容" aria-label="Permalink to “本文内容”">​</a></h3><p>本文主要聚焦在如何使用 Yocto 在 Ubuntu 上创建一个最小化的 Linux 发行版。Yocto 项目在嵌入式 Linux 的世界非常著名，这是因为它用起来非常灵活、方便。Yocto 的目标是为嵌入式软硬件开发商创建自己的 Linux 发行版。本文我们将会创建一个可以运行在 QEMU 上的最小化的 Linux，并且在 QEMU 上实际运行。</p><h3 id="开发机的基本条件" tabindex="-1">开发机的基本条件 <a class="header-anchor" href="#开发机的基本条件" aria-label="Permalink to “开发机的基本条件”">​</a></h3><ul><li>最少 4-6 GB 内存</li><li>最新版的 Ubuntu 系统（本文使用了 16.04 LTS）</li><li>磁盘剩余空间至少 60-80 GB</li><li>在创建 Linux 发行版之前先安装下面的软件包</li><li>下载最新的 Yocto（Poky 是其最小开发环境）稳定分支</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get update</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt-get install wget git-core unzip make gcc g++ build-essential subversion sed autoconf automake texi2html texinfo coreutils diffstat python-pysqlite2 docbook-utils libsdl1.2-dev libxml-parser-perl libgl1-mesa-dev libglu1-mesa-dev xsltproc desktop-file-utils chrpath groff libtool xterm gawk fop</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/1-pre_requisite_packages-1.png" alt="Install prerequisites for Yocto"></p><p>如下所示，开发环境要安装的软件包将近 1GB 大小。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/2-pre_requisite_packages-2.png" alt="Install the development packages"></p><p>在这个教程中，系统上克隆的是 poky 的 <code>morty</code> 稳定分支。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> git clone -b morty git://git.yoctoproject.org/poky.git</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/download_morty_of_yocto.png" alt="install poky"></p><p>进入 <code>poky</code> 目录，然后运行下面的命令为 Yocto 开发环境设置（设置/导出）一些环境变量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source oe-init-build-env</span></span></code></pre></div><p>如下所示，在运行了 open embedded (oe) 的构建环境脚本之后，终端里的路径会自动切换到 <code>build</code> 目录，以便进行之后行发行版的的配置和构建。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/source_environment_script.png" alt="Prepare OE build environment"></p><p>上面的截屏展示了在 <code>conf</code> 目录下创建的文件 <code>local.conf</code>。这是 Yocto 用来设置目标机器细节和 SDK 的目标架构的配置文件。</p><p>如下所示，这里设置的目标机器是 <code>qemux86-64</code>。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/selected_target.png" alt="Set the target machine type"></p><p>如下面截图所示，在 <code>local.conf</code> 中取消下面参数的注释符号。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DL_DIR ?= &quot;${TOPDIR}/downloads&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/uncheck_Download_parameters.png" alt="Configure local.conf file"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SSTATE_DIR ?= &quot;${TOPDIR}/sstate-cache&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/uncheck_sstate_parametes.png" alt="Set SSTATE_DIR"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TMPDIR ?= &quot;${TOPDIR}/tmp&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/tempdir_uncheck_paramerter.png" alt="Set TMPDIR"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PACKAGE_CLASSES ?= &quot;package_rpm&quot;</span></span>\n<span class="line"><span>SDKMACHINE ?= &quot;i686&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/sdk_and_package_selection.png" alt="Set PACKAGE_CLASSES and SDKMACHINE"></p><p>如下所示，在 <code>local.conf</code> 中为基于 Yocto 的 Linux 设置空密码和后续的一些参数。否则的话用户就不能登录进新的发行版。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>EXTRA_IMAGE_FEATURES ?= &quot;debug-tweaks&quot;</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/extra-features_for_blank_password.png" alt="Set debug-tweaks option"></p><p>我们并不准备使用任何图形化工具来创建 Linux OS，比如 <code>toaster</code> （<code>hob</code> 已经不再支持了）。</p><h3 id="yocto-编译构建过程" tabindex="-1">Yocto 编译构建过程 <a class="header-anchor" href="#yocto-编译构建过程" aria-label="Permalink to “Yocto 编译构建过程”">​</a></h3><p>现在运行下面的 <code>bitbake</code> 工具命令开始为选定的目标机器下载和编译软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bitbake core-image-minimal</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/bitbake_coreimageminimal.png" alt="Start bitbake"></p><p><strong>非常重要的是要在普通 Linux 用户下运行上面的命令，而不是使用 root 用户</strong>。如下面截图所示，当你在 root 用户下运行 bitbake 命令会产生下面所示的错误。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/dont_user_as_a_root.png" alt="Do not run bitbake as root"></p><p>再一次运行导出环境变量的脚本（<code>oe-init-build-env</code>），重新执行相同的命令来启动下载和编译过程。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/runniing_bitbake_again-normal_user.png" alt="rerun commands"></p><p>如下所示，构建脚本组件的第一步工作是解析配置（<code>recipe</code>）。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/parsing-receipe.png" alt="Parse the build recipes"></p><p>下面的截图展示了构建脚本的解析过程。同时也显示了用来构建你的新的基于 yocto 的发行版的构建系统的细节。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/output_of_parsing.png" alt="Building proceeds"></p><p>在下载了 SDK 和必要的库之后，下一步工作是下载并编译软件包。如下截图展示了为构建新发行版而执行的任务。这一步将会执行 2-3 小时，因为首先要下载需要的软件包，然后还要为新的 Linux 发行版编译这些软件包。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/task_list.png" alt="Compilation will take several hours"></p><p>下面的截图表明了任务列表执行完毕。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/downloaded-all_packages_and_compiled.png" alt=""></p><p>为目标机器类型 <code>qemux86-64</code> 编译好的新镜像位于 <code>build/tmp/deploy/images/qemux86-64</code>：</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/new_linux_compiled_under_qemux86_64.png" alt="Build complete"></p><p>如下所示，上面的命令如果运行在 <code>Putty</code> 上会产生一个错误。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/error_on_putty.png" alt="command error in putty"></p><p>通过 <code>rdp</code> 在 Ubuntu 平台上再次运行上面的命令。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/runqemu_command.png" alt="Command works fine in rdp"></p><p>为运行新的基于 Yocto 的 Linux 发行版的 qemu 打开一个新屏幕。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/new_linux_inside_the_qemu_.png" alt="Open Quemu emulator"></p><p>下面展示了新发行版的登录界面，同时也显示了使用的 yocto 项目的版本号。默认的用户名是 <code>root</code> ，密码为空。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/reference_distro.png" alt="Linux distribution started"></p><p>最后使用 <code>root</code> 用户名和空密码登录新发行版。如下截图所示，在这个最小版本的 Linux 上运行了基本的命令（<code>data</code> 、 <code>ifconfig</code> 和 <code>uname</code>）。</p><p><img src="https://www.howtoforge.com/images/how-to-create-your-own-linux-distribution-with-yocto/big/inside_new_linux_distro_running_on_qemu_3.png" alt="Test the Linux distribution"></p><p>本文的目标是理解使用 Yocto 创建新的 Linux 发行版的过程。</p><hr>',63)),a("p",null,[t[1]||(t[1]=o("via: ",-1)),e(i,{href:"https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[o("https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=o("作者：",-1)),e(i,{href:"https://www.howtoforge.com/tutorial/how-to-create-your-own-linux-distribution-with-yocto-on-ubuntu/"},{default:s(()=>[...t[2]||(t[2]=[o("Ahmad",-1)])]),_:1}),t[6]||(t[6]=o(" 译者：",-1)),e(i,{href:"https://github.com/oska874"},{default:s(()=>[...t[3]||(t[3]=[o("Ezio",-1)])]),_:1}),t[7]||(t[7]=o(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=o("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[o("Linux中国",-1)])]),_:1}),t[12]||(t[12]=o(" 荣誉推出",-1))])])}const x=n(c,[["render",d]]);export{f as __pageData,x as default};
